    ld.global.f32 %f_vb, [%r_addr];
    add.f32 %f_acc, %f_acc, %f_vb;
NO_BIAS:

    mul.wide.s32 %r_addr, %r_tid, 4;
    add.s64 %r_addr, %r_optr, %r_addr;
    st.global.f32 [%r_addr], %f_acc;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv3d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.conv3d = nn.Conv3d(in_channels, out_channels, (kernel_size, kernel_size, 1), stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        conv = self.conv3d
        N, IC, ID, IH, IW = x.shape
        OC = conv.out_channels
        kD, kH, kW = conv.kernel_size
        s = conv.stride[0]
        p = conv.padding[0]
        d = conv.dilation[0]
        g = conv.groups
        d_out = (ID + 2 * p - d * (kD - 1) - 1) // s + 1
        h_out = (IH + 2 * p - d * (kH - 1) - 1) // s + 1
        w_out = (IW + 2 * p - d * (kW - 1) - 1) // s + 1
        out = torch.empty((N, OC, d_out, h_out, w_out), dtype=x.dtype, device=x.device)
        total = out.numel()
        weight = conv.weight
        bias_t = conv.bias
        has_bias = 1 if bias_t is not None else 0
        bias_arg = bias_t if bias_t is not None else weight
        module = _get_ptx_module()
        module.launch(
            "conv3d_kernel",
            grid=((total + 255) // 256, 1, 1),
            block=(256, 1, 1),
            arguments=[
                x, weight, out, bias_arg,
                i32(total), i32(OC), i32(IC),
                i32(d_out), i32(h_out), i32(w_out),
                i32(ID), i32(IH), i32(IW),
                i32(kD), i32(kH), i32(kW),
                i32(IC // g), i32(OC // g),
                i32(s), i32(p), i32(d), i32(has_bias),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
